<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';import {createPmsEcho} from './realtime';import {pmsApi} from './api';
const props=defineProps<{projectId:number;csrf?:string}>();const messages=ref<any[]>([]),text=ref(''),reply=ref<any>(null),busy=ref(false),error=ref(''),state=ref('Connecting');let echo:any;
async function load(){try{messages.value=await pmsApi('projects/'+props.projectId+'/chat');await pmsApi('projects/'+props.projectId+'/chat/seen',props.csrf,'POST',{});}catch(e){error.value=(e as Error).message;}}
async function send(){busy.value=true;error.value='';try{const result=await pmsApi('projects/'+props.projectId+'/chat',props.csrf,'POST',{message:text.value,parent_id:reply.value?.id||null});text.value='';reply.value=null;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(id:number){if(!confirm('Delete this project message?'))return;try{await pmsApi('project-chat/'+id,props.csrf,'DELETE');await load();}catch(e){error.value=(e as Error).message;}}
onMounted(async()=>{await load();echo=await createPmsEcho(props.csrf||'');if(!echo){state.value='Realtime disabled';return;}echo.private('pms.project.chat.'+props.projectId).listen('.ProjectChatMessageSent',()=>void load()).subscribed(()=>state.value='Live').error(()=>state.value='Disconnected');echo.connector.pusher.connection.bind('state_change',({current}:{current:string})=>state.value=current);});onUnmounted(()=>echo?.disconnect());
</script><template><section class="card p-4 my-3"><div class="admin-section-heading"><h3>Project conversation</h3><small>{{state}}</small></div><p v-if="error" class="notice admin-error">{{error}}</p><div style="max-height:420px;overflow:auto"><article v-for="m in messages" :key="m.id" class="pms-comment-list"><strong>{{m.sender?.name||m.author_name||'Administrator'}}</strong><small>{{m.created_at_human}}</small><p style="white-space:pre-wrap">{{m.message}}</p><div class="row-actions"><button @click="reply=m">Reply</button><button v-if="m.can_delete" @click="remove(m.id)">Delete</button></div><div v-for="r in m.replies" :key="r.id" style="margin:12px 0 12px 24px;border-left:2px solid #696cff;padding-left:12px"><strong>{{r.sender?.name||r.author_name||'Administrator'}}</strong><p style="white-space:pre-wrap">{{r.message}}</p><small>{{r.created_at_human}}</small><button v-if="r.can_delete" class="button" @click="remove(r.id)">Delete</button></div></article><p v-if="!messages.length" class="muted">No project messages yet.</p></div><form @submit.prevent="send"><p v-if="reply">Replying to {{reply.sender?.name||reply.author_name}} <button type="button" class="button" @click="reply=null">Cancel</button></p><label>Message<textarea v-model="text" maxlength="5000" required></textarea></label><button class="button primary" :disabled="busy||!text.trim()">{{busy?'Sending...':'Send message'}}</button></form></section></template>